// Макеты LidRadar для ручного импорта. Все данные — демонстрационные.
// Повторяющиеся элементы собираются из общих функций; SVG не содержит растра.
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const MODULES = process.env.LIDRADAR_NODE_MODULES || path.join(ROOT,'node_modules');
await fs.mkdir(path.join(ROOT, 'svg'), {recursive:true});
await fs.mkdir(path.join(ROOT, 'preview'), {recursive:true});
const iconNames = ['radar','messages-square','chart-no-axes-combined','plug','settings','chevron-down','chevron-right','arrow-left','arrow-right','check','check-check','circle-check','circle-alert','triangle-alert','clock','search','plus','external-link','copy','eye','eye-off','mail','lock-keyhole','building-2','map-pin','calendar-days','bell','users','sliders-horizontal','refresh-cw','x','circle-help','shield-check','log-out','ellipsis','send','file-text','wifi-off','receipt','check-circle-2'];
let icons = {};
try { icons = JSON.parse(await fs.readFile(path.join(ROOT,'source','icons.json'),'utf8')); }
catch { for(const n of iconNames) { try {icons[n]=(await import(pathToFileURL(path.join(MODULES,'lucide','dist','esm','icons',`${n}.js`)))).default;} catch { /* Необязательный псевдоним. */ } } await fs.writeFile(path.join(ROOT,'source','icons.json'),JSON.stringify(icons,null,2)); }
if(!icons['circle-help']) {icons['circle-help']=(await import(pathToFileURL(path.join(MODULES,'lucide','dist','esm','icons','circle-question-mark.js')))).default;await fs.writeFile(path.join(ROOT,'source','icons.json'),JSON.stringify(icons,null,2));}
try {await fs.copyFile(path.join(MODULES,'lucide','LICENSE'),path.join(ROOT,'source','LUCIDE-LICENSE'));} catch {}

const C={bg:'#F5F7FB',paper:'#FFFFFF',ink:'#191E2B',muted:'#63718A',faint:'#63718A',line:'#E1E7F0',nav:'#0E1422',navActive:'#1C2435',navText:'#BAC2D2',brand:'#6C55FF',brandDark:'#5640D8',brandPale:'#F0EDFF',green:'#087D50',greenPale:'#ECFBF3',red:'#D22A25',redPale:'#FFF3F2',amber:'#AD5B11',amberPale:'#FFF6E8',blue:'#1768C6',bluePale:'#EDF6FF'};
let items=[], seq=0, currentId='';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const add=s=>{items.push(s);};
const group=(name,fn)=>{add(`<g id="${esc(name)}">`);fn();add('</g>');};
function rect(x,y,w,h,fill=C.paper,r=0,stroke='none',sw=1){add(`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>`);}
function line(x1,y1,x2,y2,col=C.line,sw=1){add(`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${sw}"/>`);}
function circle(x,y,r,fill,stroke='none',sw=1){add(`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>`);}
function txt(s,x,y,size=14,col=C.ink,weight=400,w=0,anchor='start'){
  add(`<text id="text-${++seq}" x="${x}" y="${y}" font-family="Inter" font-size="${size}" font-weight="${weight}" fill="${col}" text-anchor="${anchor}"${w?` data-max-width="${w}"`:''}>${esc(s)}</text>`);
}
function lines(arr,x,y,size=14,col=C.muted,weight=400,lh=22,w=0){arr.forEach((s,i)=>txt(s,x,y+i*lh,size,col,weight,w));}
function icon(name,x,y,size=20,col=C.muted){const nodes=icons[name]||icons['circle-help'];add(`<g id="icon-${name}-${++seq}" transform="translate(${x} ${y}) scale(${size/24})" fill="none" stroke="${col}" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${nodes.map(([t,a])=>`<${t} ${Object.entries(a).map(([k,v])=>`${k}="${esc(v)}"`).join(' ')}/>`).join('')}</g>`);}
function button(label,x,y,w=160,kind='primary',ico=null,h=44){group(`button-${++seq}`,()=>{let fill=kind==='primary'?C.brand:kind==='soft'?C.brandPale:kind==='danger'?C.redPale:C.paper;let color=kind==='primary'?'#FFFFFF':kind==='soft'?C.brandDark:kind==='danger'?C.red:C.ink;rect(x,y,w,h,fill,11,kind==='secondary'?C.line:'none');if(ico)icon(ico,x+16,y+(h-18)/2,18,color);txt(label,ico?x+43:x+w/2,y+h/2+4.5,13,color,600,w-(ico?56:24),ico?'start':'middle');});}
function badge(s,x,y,w,kind='neutral'){const [fg,bg]=kind==='green'?[C.green,C.greenPale]:kind==='red'?[C.red,C.redPale]:kind==='amber'?[C.amber,C.amberPale]:kind==='brand'?[C.brandDark,C.brandPale]:kind==='blue'?[C.blue,C.bluePale]:[C.muted,C.bg];rect(x,y,w,28,bg,14);txt(s,x+w/2,y+18,11,fg,600,w-16,'middle');}
function field(label,value,x,y,w=320,{hint='',select=false,error='',iconName=null}={}){txt(label,x,y,12,C.muted,600,w);rect(x,y+12,w,46,C.paper,10,error?C.red:C.line);if(iconName)icon(iconName,x+14,y+25,18,C.faint);txt(value,x+(iconName?42:14),y+41,14,value?C.ink:C.faint,400,w-(select?50:28)-(iconName?26:0));if(select)icon('chevron-down',x+w-31,y+26,16,C.muted);if(hint)txt(hint,x,y+79,11,C.muted,400,w);if(error)txt(error,x,y+79,11,C.red,500,w);}
function checkRow(s,x,y,checked=true,col=C.ink,w=450){rect(x,y-14,18,18,checked?C.brand:C.paper,5,checked?C.brand:C.line);if(checked)icon('check',x+2,y-12,14,'#fff');txt(s,x+29,y,13,col,400,w-29);}
function toggle(x,y,on=true){rect(x,y,40,24,on?C.brand:'#CDD5E2',12);circle(x+(on?28:12),y+12,9,C.paper);}
function panel(x,y,w,h,title='',sub=''){rect(x,y,w,h,C.paper,18,C.line);if(title)txt(title,x+24,y+34,17,C.ink,650,w-48);if(sub)txt(sub,x+24,y+57,12,C.muted,400,w-48);}
function notice(x,y,w,title,desc,kind='blue',h=82){const [fg,bg]=kind==='green'?[C.green,C.greenPale]:kind==='red'?[C.red,C.redPale]:kind==='amber'?[C.amber,C.amberPale]:[C.blue,C.bluePale];rect(x,y,w,h,bg,12);icon(kind==='green'?'circle-check':kind==='red'?'circle-alert':'circle-help',x+16,y+18,20,fg);txt(title,x+48,y+30,13,fg,600,w-66);if(Array.isArray(desc))lines(desc,x+48,y+52,12,fg,400,19,w-66);else txt(desc,x+48,y+53,12,fg,400,w-66);}
function divider(x,y,w){line(x,y,x+w,y);}
function logo(x,y,dark=false){icon('radar',x,y-19,25,dark?C.brand:C.paper);txt('LidRadar',x+34,y,21,dark?C.ink:C.paper,700,140);}
function shell(active,title,subtitle,{h=1024,telegram=true}={}){
  rect(0,0,1440,h,C.bg);group('Sidebar',()=>{rect(0,0,232,h,C.nav);logo(24,49);txt('РАБОЧЕЕ ПРОСТРАНСТВО',24,99,10,'#7E8BA5',650,190);const nav=[['Radar','radar'],['Диалоги','messages-square'],['Аналитика','chart-no-axes-combined'],['Интеграции','plug'],['Настройки','settings']];nav.forEach(([label,ic],i)=>{const yy=120+i*54;if(label===active){rect(16,yy,200,44,C.navActive,12);rect(16,yy+10,3,24,C.brand,2);}icon(ic,32,yy+12,20,label===active?'#FFFFFF':C.navText);txt(label,64,yy+28,14,label===active?'#FFFFFF':C.navText,label===active?600:400,135);});line(24,h-99,208,h-99,'#263047');circle(42,h-58,18,'#293347');txt('DL',42,h-54,11,'#FFFFFF',700,30,'middle');txt('Detail Lab',70,h-61,13,'#FFFFFF',600,135);txt('Владелец',70,h-41,11,'#8996AE',400,130);icon('chevron-down',190,h-64,16,'#8996AE');});
  group('Header',()=>{rect(232,0,1208,80,C.paper);txt(title,280,35,21,C.ink,700,600);txt(subtitle,280,59,12,C.muted,400,680);if(telegram)badge('Telegram подключён',1190,24,202,'green');else badge('Демонстрационный макет',1160,24,232,'neutral');});
}
function heading(title,sub,y=136){txt(title,280,y,29,C.ink,700,1050);if(sub)txt(sub,280,y+28,13,C.muted,400,1070);}
function tabs(active,y=200){const vals=['Компания и график','Услуги','Уведомления','Команда','Данные'];let x=280;vals.forEach((s,i)=>{const w=[190,96,158,108,96][i];txt(s,x+12,y,13,s===active?C.brandDark:C.muted,s===active?650:500,w-20);if(s===active)rect(x,y+16,w,3,C.brand,2);x+=w+12;});line(280,y+19,1392,y+19);}
function setupShell(step,title,subtitle){rect(0,0,1440,1024,C.bg);rect(0,0,380,1024,C.nav);logo(48,57);txt('НАЧАЛО РАБОТЫ',48,126,11,'#8D99B0',650,270);const labels=['Компания','Рабочее время','Услуги и цены','Telegram'];labels.forEach((s,i)=>{const y=174+i*84;circle(64,y,16,i+1<=step?C.brand:'#253048');if(i+1<step)icon('check',54,y-10,20,C.paper);else txt(i+1,64,y+5,12,C.paper,650,24,'middle');txt(s,98,y+5,15,i+1<=step?C.paper:'#9AA7BE',600,210);if(i<3)line(64,y+26,64,y+58,'#35405A');});rect(40,758,300,182,'#1B2436',16);icon('shield-check',62,780,23,'#AFA4FF');lines(['Вы управляете действиями.', 'LidRadar помогает заметить', 'риск и выбрать следующий шаг.'],62,829,14,'#E0E4EE',500,23,258);txt('Самостоятельно клиентам не пишет.',62,914,11,'#A4B0C6',400,258);txt(`Шаг ${step} из 4`,460,72,12,C.brandDark,600,650);txt(title,460,132,30,C.ink,700,872);lines(Array.isArray(subtitle)?subtitle:[subtitle],460,162,14,C.muted,400,23,870);}
function setupBottom(step,primary='Продолжить'){divider(460,905,888);if(step>1)button('Назад',460,930,122,'secondary','arrow-left');txt('Настройки можно изменить позже',step>1?610:460,958,12,C.muted,400,410);button(primary,1146,930,202,'primary','arrow-right');}
function screen(id,title,description,fn,h=1024,device='Макет для компьютера.'){items=[];seq=0;currentId=id;fn();const xml=`<?xml version="1.0" encoding="UTF-8"?>\n<svg xmlns="http://www.w3.org/2000/svg" width="1440" height="${h}" viewBox="0 0 1440 ${h}" fill="none" role="img" aria-labelledby="title desc"><title id="title">${esc(title)}</title><desc id="desc">${esc(description)} Демонстрационные данные. ${device}</desc>${items.join('\n')}</svg>\n`;screens.push({id,title,description,width:1440,height:h,svg:xml});}
const screens=[];

screen('01-vhod','Вход в LidRadar','Вход по электронной почте и паролю без неподдерживаемого восстановления пароля.',()=>{
  rect(0,0,1440,1024,C.bg);rect(0,0,620,1024,C.nav);logo(64,62);badge('КОНТРОЛЬ ПОТЕРЯННЫХ ВОЗМОЖНОСТЕЙ',64,180,350,'brand');lines(['Замечайте риски.', 'Возвращайте', 'клиентов.'],64,302,46,C.paper,700,61,500);lines(['Переписка, причина риска и следующий шаг —', 'в одном рабочем пространстве.'],64,516,16,'#B9C4D8',400,27,493);rect(64,660,492,190,'#1B2436',18);icon('radar',88,686,28,'#AFA3FF');txt('Деньги требуют внимания',133,708,18,C.paper,650,380);lines(['Понятные причины вместо догадок.', 'Решение и ответ клиенту остаются за вами.'],88,764,14,'#BCC7DA',400,26,420);txt('LidRadar · Для малого бизнеса',64,960,12,'#8B99B0',400,470);
  txt('С возвращением',746,250,32,C.ink,700,560);txt('Войдите в своё рабочее пространство',746,285,14,C.muted,400,545);field('Электронная почта','owner@example.test',746,352,560,{iconName:'mail'});field('Пароль','••••••••••••',746,454,560,{iconName:'lock-keyhole'});icon('eye',1270,481,20,C.muted);button('Войти',746,569,560);divider(746,656,560);txt('Впервые в LidRadar?',746,698,14,C.muted,400,300);txt('Создать аккаунт',1306,698,14,C.brandDark,650,200,'end');notice(746,754,560,'Безопасный вход',['Данные организаций разделены.', 'После входа доступны только ваши рабочие пространства.'],'blue',105);
});

