// ---- v0.3: листы 17–32 (закрывают GAP-DESIGN-014/015/018). Персона та же, что в v0.2: Detail Lab, точка «Студия на Пресне»;
// ---- имена и суммы согласованы с демонстрационным набором e2e (Дмитрий Соколов, Полировка кузова, 31 000 ₽, Анна Смирнова).
const wrap=(s,n)=>{const out=[];let cur='';for(const w of String(s).split(' ')){if(cur&&(cur+' '+w).length>n){out.push(cur);cur=w;}else cur=cur?cur+' '+w:w;}if(cur)out.push(cur);return out;};
function para(s,x,y,size,col,weight,lh,w){const ls=Array.isArray(s)?s:wrap(s,Math.floor(w/(size*0.56)));lines(ls,x,y,size,col,weight,lh,w);return ls.length;}
function sevBadge(sev,x,y){const map={'Критично':['red',96],'Высокий':['amber',92],'Средний':['blue',92],'Низкий':['neutral',84]};const [k,w]=map[sev]||['neutral',90];badge(sev,x,y,w,k);return w;}
function riskCard(x,y,w,{sev,type,name,service,potential,due,status,action='Открыть'}){rect(x,y,w,124,C.paper,16,C.line);const bw=sevBadge(sev,x+20,y+18);badge(type,x+28+bw,y+18,Math.min(240,type.length*7.6+28),'neutral');if(status)badge(status,x+w-160,y+18,140,status==='В работе'?'brand':'neutral');txt(name,x+20,y+74,17,C.ink,650,w-440);txt(service,x+20,y+97,12,C.muted,400,w-440);txt(potential,x+w-190,y+74,17,C.ink,700,200,'end');txt(due,x+w-190,y+97,11,C.red,600,220,'end');button(action,x+w-150,y+64,130,'secondary','arrow-right',36);}
function skeleton(x,y,w,h){rect(x,y,w,h,'#E3E8F0',8);}
function overlay(h=1024){add(`<rect x="0" y="0" width="1440" height="${h}" fill="#0E1422" opacity="0.46"/>`);}
function dialog(x,y,w,h,title,desc=[]){panel(x,y,w,h);txt(title,x+32,y+46,22,C.ink,700,w-100);icon('x',x+w-52,y+27,20);lines(Array.isArray(desc)?desc:[desc],x+32,y+80,13,C.muted,400,21,w-64);}
function kv(label,value,x,y,w,valueColor=C.ink,split=0.38){txt(label,x,y,12,C.muted,400,w*split-8);txt(value,x+w*split,y,13,valueColor,550,w*(1-split));}
function adminShell(active,title,{h=1024}={}){
  rect(0,0,1440,h,C.bg);group('AdminSidebar',()=>{rect(0,0,232,h,C.nav);logo(24,49);txt('АДМИНИСТРИРОВАНИЕ ПЛАТФОРМЫ',24,84,10,'#F0EDFF',650,200);const nav=['Обзор','Организации','Подключения','Задания','Мёртвые письма','AI','Потребление','Трассировка','Администраторы'];nav.forEach((label,i)=>{const yy=110+i*44;if(label===active){rect(16,yy,200,36,C.navActive,10);}txt(label,32,yy+23,13,label===active?'#FFFFFF':C.navText,label===active?600:400,170);});line(24,h-131,208,h-131,'#263047');txt('Мария Владелец',24,h-100,13,'#FFFFFF',600,180);txt('← В рабочее пространство',24,h-74,12,C.navText,600,190);rect(24,h-56,184,36,C.paper,10);txt('Выйти',116,h-33,13,C.ink,600,120,'middle');});
  group('AdminHeader',()=>{rect(232,0,1208,72,C.paper);txt('ТОЛЬКО МЕТАДАННЫЕ',280,30,10,C.muted,650,300);txt(title,280,55,19,C.ink,700,700);});
}
function snapshotBar(x,y,w,when='Снимок на 25 сент., 08:31 UTC'){txt(when,x,y+22,13,C.muted,400,w-160);button('Обновить',x+w-118,y,118,'secondary',null,36);}
function idChip(x,y,id){rect(x,y-14,96,22,C.bg,6);txt(id,x+8,y+2,11,C.ink,500,68);icon('copy',x+76,y-11,14,C.brandDark);}
function frame(x,y,scale,w,h,fn){add(`<g transform="translate(${x} ${y}) scale(${scale})">`);rect(0,0,w,h,C.bg,28,C.line,2);const id=`clip-${currentId}-${++seq}`;add(`<clipPath id="${id}"><rect x="0" y="0" width="${w}" height="${h}" rx="28"/></clipPath>`);add(`<g clip-path="url(#${id})">`);fn();add('</g></g>');}
function phoneHeader(title,org='DETAIL LAB'){rect(0,0,375,64,C.paper);txt(org,20,26,9,C.muted,650,220);txt(title,20,48,16,C.ink,700,220);rect(299,16,60,32,C.paper,8,C.line);txt('Меню',329,37,12,C.ink,600,48,'middle');}
function phoneButton(label,x,y,w,kind='primary'){button(label,x,y,w,kind,null,44);}
function caption(x,y,w,title,body){txt(title,x,y,14,C.ink,650,w);para(body,x,y+22,12,C.muted,400,18,w);}

